-- One-time bonus searches. Written only by the server (service role); a person can read their own row.
CREATE TABLE IF NOT EXISTS public.search_bonus (
  user_id    UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  granted    INTEGER NOT NULL DEFAULT 4 CHECK (granted >= 0),
  used       INTEGER NOT NULL DEFAULT 0 CHECK (used >= 0),
  granted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
ALTER TABLE public.search_bonus ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS search_bonus_read_own ON public.search_bonus;
CREATE POLICY search_bonus_read_own ON public.search_bonus FOR SELECT USING (auth.uid() = user_id);
REVOKE ALL ON public.search_bonus FROM anon, authenticated;
GRANT SELECT ON public.search_bonus TO authenticated;

-- Atomically spend one bonus search. Creates the 4-search grant the first time it is called
-- (the caller has already checked the profile is complete). Returns true if a search was spent.
CREATE OR REPLACE FUNCTION public.use_search_bonus(p_user_id UUID, p_grant INTEGER DEFAULT 4)
RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE v_rows INTEGER;
BEGIN
  INSERT INTO public.search_bonus (user_id, granted) VALUES (p_user_id, p_grant) ON CONFLICT (user_id) DO NOTHING;
  UPDATE public.search_bonus SET used = used + 1 WHERE user_id = p_user_id AND used < granted;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  RETURN v_rows = 1;
END; $$;
REVOKE ALL ON FUNCTION public.use_search_bonus(UUID, INTEGER) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.use_search_bonus(UUID, INTEGER) TO service_role;

-- Give a bonus search back (our side failed). Never goes below zero.
CREATE OR REPLACE FUNCTION public.refund_search_bonus(p_user_id UUID)
RETURNS VOID
LANGUAGE sql SECURITY DEFINER SET search_path = public
AS $$ UPDATE public.search_bonus SET used = GREATEST(used - 1, 0) WHERE user_id = p_user_id; $$;
REVOKE ALL ON FUNCTION public.refund_search_bonus(UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.refund_search_bonus(UUID) TO service_role;
